import{_ as i,c as n,o as a,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"REINVIGORATING THE NUCLEAR INDUSTRIAL BASE","description":"","frontmatter":{"title":"REINVIGORATING THE NUCLEAR INDUSTRIAL BASE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/reinvigorating-the-nuclear-industrial-base/","publishDate":"2025-05-23T17:13:04-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-23-reinvigorating-the-nuclear-industrial-base.md","filePath":"executive-orders/2025-05-23-reinvigorating-the-nuclear-industrial-base.md"}'),t={name:"executive-orders/2025-05-23-reinvigorating-the-nuclear-industrial-base.md"};function l(o,e,s,u,c,p){return a(),n("div",null,e[0]||(e[0]=[r('<h1 id="reinvigorating-the-nuclear-industrial-base" tabindex="-1">REINVIGORATING THE NUCLEAR INDUSTRIAL BASE <a class="header-anchor" href="#reinvigorating-the-nuclear-industrial-base" aria-label="Permalink to &quot;REINVIGORATING THE NUCLEAR INDUSTRIAL BASE&quot;">​</a></h1><p>Published: Friday, May 23, 2025</p><ul><li><p><strong>Background</strong></p><ul><li>The U.S. faces challenges in energy independence and securing national security through nuclear energy.</li><li>The country&#39;s nuclear capacity growth has lagged compared to other developed nations.</li><li>There is heavy reliance on foreign sources for uranium and nuclear fuel cycle services.</li></ul></li><li><p><strong>Goals of the Executive Order</strong></p><ul><li>Expedite nuclear energy production and operation.</li><li>Enhance national security and energy independence.</li><li>Develop supply chains for advanced nuclear technologies.</li></ul></li><li><p><strong>Key Action Items</strong></p><ul><li><p><strong>Report to the President (240 days)</strong></p><ul><li>Recommend national policy for managing spent nuclear fuel and waste.</li><li>Review statutory authorities for necessary legislative changes.</li><li>Evaluate spent nuclear fuel recycling processes.</li><li>Analyze legal and budgetary considerations for fuel transfer.</li><li>Develop recommendations for efficient use and disposal of nuclear waste.</li></ul></li><li><p><strong>Plan for Uranium Capacity (120 days)</strong></p><ul><li>Expand domestic uranium conversion and enrichment capacities.</li><li>Ensure sufficient stockpiles for national defense and civilian needs.</li></ul></li><li><p><strong>Surplus Plutonium Disposal (Secretary of Energy&#39;s actions)</strong></p><ul><li>Establish a program to process surplus plutonium for industry use.</li></ul></li><li><p><strong>Nuclear Waste Management Policy Update (90 days)</strong></p><ul><li>Align the policy with national security needs and modernize the nuclear weapons stockpile.</li></ul></li><li><p><strong>Support for Domestic Nuclear Energy Companies (30 days)</strong></p><ul><li>Form voluntary agreements to enhance collaboration and resource sharing.</li></ul></li></ul></li><li><p><strong>Prioritizing Nuclear Capacity Expansion</strong></p><ul><li>Focus on 5 gigawatt power uprates and developing 10 new large reactors by 2030.</li><li>Revise policies to support the restart of closed nuclear plants for military energy resilience.</li></ul></li><li><p><strong>Funding and Support for Advanced Nuclear Technologies</strong></p><ul><li>Prioritize grants and loans for advanced nuclear tech development.</li><li>Collaborate with the Small Business Administration for financial support.</li></ul></li><li><p><strong>Education and Workforce Development</strong></p><ul><li>Encourage education and career pathways in nuclear energy careers.</li><li>Increase participation in apprenticeships and practical learning opportunities in the nuclear sector.</li></ul></li><li><p><strong>Legal and Compliance Notes</strong></p><ul><li>Ensure adherence to budgetary, legislative, and nonproliferation obligations.</li><li>This order does not create enforceable rights against the United States or its agencies.</li></ul></li><li><p><strong>Implementation Considerations</strong></p><ul><li>Actions must align with existing legal frameworks and available funding.</li><li>The Department of Energy is tasked with publication and dissemination of this order.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/reinvigorating-the-nuclear-industrial-base/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/reinvigorating-the-nuclear-industrial-base/</a></p>',4)]))}const h=i(t,[["render",l]]);export{g as __pageData,h as default};
